ground_truth_sql:
SELECT "nct", "author", "year", "publication_type", "ici_name", "follow_up_duration_overall_months", "cancer_type", "trial_phase"
FROM public."clinical_trials"
WHERE "cancer_type" = 'Head and Neck' AND "ici_name" = 'Nivolumab' AND NULLIF(regexp_replace(("follow_up_duration_overall_months")::text, '[^0-9\.-]', '', 'g'), '')::numeric > 21;

gt_sql_final:
SELECT "nct", "author", "year", "originial_publication_or_follow_up", "name_of_ici", "follow_up_duration_for_primary_endpoint_s_in_months_overall", "cancer_type", "trial_phase"
FROM public."clinical_trials"
WHERE "cancer_type" = 'Head and Neck' AND "name_of_ici" = 'Nivolumab' AND NULLIF(regexp_replace(("follow_up_duration_for_primary_endpoint_s_in_months_overall")::text, '[^0-9\.-]', '', 'g'), '')::numeric > 21;
